INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3330315, 463681, 43774, '<td valign="top">great job, love the tones of this</td>', 'great job, love the tones of this', '2007-02-05 11:39:35.000000', NULL, 1),
(3330319, 463924, 43774, '<td valign="top">Very cool, looks like a bone on top of an old tree? Good set up and well photographed.</td>', 'Very cool, looks like a bone on top of an old tree? Good set up and well photographed.', '2007-02-05 11:40:06.000000', NULL, 1),
(3330320, 463846, 26045, '<td valign="top">incredible photo! this is so very clever, and the technical nature of the photo (lighting, dramatic b/w) lends so well to the subject. pink floyd would be proud. it''s dark, but also humorous. it''s creepy, too, which adds so much! it''s actually a very sophisticated photo and it caught my eye instantly. i hope you are given due praise for this. 10</td>', 'incredible photo! this is so very clever, and the technical nature of the photo (lighting, dramatic b/w) lends so well to the subject. pink floyd would be proud. it''s dark, but also humorous. it''s creepy, too, which adds so much! it''s actually a very sophisticated photo and it caught my eye instantly. i hope you are given due praise for this. 10', '2007-02-05 11:40:16.000000', NULL, 1),
(3330322, 462944, 43774, '<td valign="top">Cute! Nice job adding the smiling face</td>', 'Cute! Nice job adding the smiling face', '2007-02-05 11:40:29.000000', NULL, 1),
(3330324, 460796, 43774, '<td valign="top">Very good job</td>', 'Very good job', '2007-02-05 11:40:39.000000', NULL, 1),
(3330326, 464065, 43774, '<td valign="top">Cute, well done.</td>', 'Cute, well done.', '2007-02-05 11:40:52.000000', NULL, 1),
(3330327, 463949, 26045, '<td valign="top">ahaha, very nice :) i think you did a great job - very simple, the title is just perfect - and the colors just pop on the screen. impressive work, and good luck! 10</td>', 'ahaha, very nice :) i think you did a great job - very simple, the title is just perfect - and the colors just pop on the screen. impressive work, and good luck! 10', '2007-02-05 11:40:54.000000', NULL, 1),
(3330330, 463750, 66384, '<td valign="top">Great idea, beautifully executed. I would have liked to see the Mum''s face and the tiny rose highlighted a little more. The hot spot on the napkin draws the eye away from the primary subject(s).</td>', 'Great idea, beautifully executed. I would have liked to see the Mum''s face and the tiny rose highlighted a little more. The hot spot on the napkin draws the eye away from the primary subject(s).', '2007-02-05 11:41:11.000000', NULL, 1),
(3330338, 463755, 26045, '<td valign="top">ah, of all the bathroom-fixture photos in this challenge, i think yours is most deserving. the blue tones are extremely complementary to the subject and tone of the photo. in fact, it is the tone of this photo that does so well. the title is a bit too-too, but who cares about titles?! i think you did an excellent job of capturing a fabricated emotion. the water''s motion also adds a great touch. very impressive! good luck in the challenge, i hope you get due praise! 10</td>', 'ah, of all the bathroom-fixture photos in this challenge, i think yours is most deserving. the blue tones are extremely complementary to the subject and tone of the photo. in fact, it is the tone of this photo that does so well. the title is a bit too-too, but who cares about titles?! i think you did an excellent job of capturing a fabricated emotion. the water''s motion also adds a great touch. very impressive! good luck in the challenge, i hope you get due praise! 10', '2007-02-05 11:42:31.000000', NULL, 1),
(3330353, 463370, 26045, '<td valign="top">ha! how wonderful is this!? i LOVE the fabric, as it really does parody so many cliche maternity shots. the shape of the fruit(s) is just right, the lighting is good, and the tone of the photo is spot on. even the title''s simplicity aids to the photo. i think you did a great job, and i wish you good luck in the challenge. 10</td>', 'ha! how wonderful is this!? i LOVE the fabric, as it really does parody so many cliche maternity shots. the shape of the fruit(s) is just right, the lighting is good, and the tone of the photo is spot on. even the title''s simplicity aids to the photo. i think you did a great job, and i wish you good luck in the challenge. 10', '2007-02-05 11:44:32.000000', NULL, 1),
(3330363, 463911, 26045, '<td valign="top">wonderful wonderful! the simplicity is really helping the photo - in color, shadow, lighting, even title.... the delicate motion of the leaf represents the emotion so well...i am very impressed! i hope this does well, it''s a great photo. 10</td>', 'wonderful wonderful! the simplicity is really helping the photo - in color, shadow, lighting, even title.... the delicate motion of the leaf represents the emotion so well...i am very impressed! i hope this does well, it''s a great photo. 10', '2007-02-05 11:45:33.000000', NULL, 1),
(3330371, 464065, 26045, '<td valign="top">excellent idea! i think you did very well with this photo, in all aspects. the emotion is palpable, so you succeeded. good luck in the challenge! 10</td>', 'excellent idea! i think you did very well with this photo, in all aspects. the emotion is palpable, so you succeeded. good luck in the challenge! 10', '2007-02-05 11:46:21.000000', NULL, 1),
