(3334139, 463552, 24073, '<td valign="top">A bit over-sharpened, but no worries, its still an awesome photo.  -9.</td>', 'A bit over-sharpened, but no worries, its still an awesome photo.  -9.', '2007-02-06 09:25:00.000000', NULL, 1),
(3334141, 463378, 24073, '<td valign="top">I''m going out on a limb here, and giving this a full 9.  This is the reason, your colors are dynamite, your composition is exceptional, and your idea is unique.  The way you handled the lighted areas in this photo, rather execution or post process, its awesome.  GL, I''ll be cheering ya on.</td>', 'I''m going out on a limb here, and giving this a full 9.  This is the reason, your colors are dynamite, your composition is exceptional, and your idea is unique.  The way you handled the lighted areas in this photo, rather execution or post process, its awesome.  GL, I''ll be cheering ya on.', '2007-02-06 09:25:26.000000', NULL, 1),
(3334197, 463757, 39566, '<td valign="top">this is amazing, you obviously spent some time on this. Hope you do well. 10</td>', 'this is amazing, you obviously spent some time on this. Hope you do well. 10', '2007-02-06 09:44:28.000000', NULL, 1),
